import React, {Component} from 'react';
import {Image, Text, TextInput, ToastAndroid, TouchableNativeFeedback, View,} from 'react-native';
import {bindActionCreators} from 'redux';
import {connect} from 'react-redux';
import axios from 'axios';
import styles from './LoginStyles';
import {userDataUpdate} from "../../Redux/User/UserActions";
import {goTo} from "../../Redux/Navigation/NavigationActions";
import firebaseApp from '../Firebase.js';
import SmsListener from 'react-native-android-sms-listener'

firebaseApp.analytics().setCurrentScreen("Phone_OTP");

class Phone extends Component<{}> {
  formatTime = ms => {
    const minutes = Math.floor(ms / 60000);
    const seconds = ((ms % 60000) / 1000).toFixed(0);
    return '0' + minutes + ":" + (seconds < 10 ? '0' : '') + seconds;
  };
  retryOTP = mode => {
    axios.post(`http://control.msg91.com/api/retryotp.php?authkey=205294A7mPXVfgk5ab3b5bf&mobile=${this.state.phone.value}&retrytype=${mode}`)
      .then(({data}) => {
        if (data.type === 'success') {
          ToastAndroid.show('OTP was sent to the requested phone', ToastAndroid.SHORT);
        }
        else {
          ToastAndroid.show('OTP failed to send.', ToastAndroid.SHORT);
        }
      firebaseApp.analytics().logEvent('retryOTP');

      })
  };
  verifyPhone = phone => {
    return {
      valid: phone.length === 10,
      value: phone
    }
  };
  submit = () => {
    if (!this.state.phone.value) {
      ToastAndroid.show('Enter the phone number to proceed.', ToastAndroid.SHORT);
      return;
    }
    this.props.userDataUpdate({
      phone: '+91' + this.state.phone.value,
    });
    axios.post(`http://control.msg91.com/api/sendotp.php?authkey=205294A7mPXVfgk5ab3b5bf&sender=CLASSCAST&mobile=${this.state.phone.value}`)
      .then(({data}) => {
        console.log(data);
        if (data.type === 'success') {
          this.setState({
            otpSent: true,
            startTime: new Date(),
          });
          setInterval(() => {
            this.setState({
              currentTime: new Date(),
            })
          }, 500);
        }
        else {
          ToastAndroid.show(data.message, ToastAndroid.SHORT);
        }
      })
      .catch(e => {
        console.log(e);
        console.log(e.response);
      })
  };
  submitOTP = () => {
    let otp = this.state.otp;
    if (!otp[0] || !otp[1] || !otp[2] || !otp[3]) {
      ToastAndroid.show('Check the OTP', ToastAndroid.SHORT);
      return;
    }
    const otpValue = otp.reduce((value, current) => value + current.toString());

    axios.post(`https://control.msg91.com/api/verifyRequestOTP.php?authkey=205294A7mPXVfgk5ab3b5bf&mobile=${this.state.phone.value}&otp=${otpValue}`)
      .then(({data}) => {
        console.log(data);
        if (data.type === 'success') {
          this.props.userDataUpdate({phone: this.state.phone.value});
          this.props.goTo([0, 3]);
          firebaseApp.analytics().logEvent('OTPverification_success');

        }
        else {
          ToastAndroid.show('OTP Verification Failed', ToastAndroid.SHORT);
          firebaseApp.analytics().logEvent('OTPverification_failed');

        }
      })
      .catch(e => {
        ToastAndroid.show('OTP Verification Failed', ToastAndroid.SHORT);
        firebaseApp.analytics().logEvent('OTPverification_failed' , {reason: e});

        console.log(e);
        console.log(e.response);
      })
  }

  constructor() {
    super();
    this.state = {
      phone: {
        valid: true,
        value: '',
        submitted: false,
      },
      otp: [
        '',
        '',
        '',
        '',
      ],
      otpSent: false,
      startTime: null,
      currentTime: null,
      timeout: 25000,
    };
    this.submit = this.submit.bind(this);
  }

  componentDidMount() {
    let sub = SmsListener.addListener(message => {
      alert(message.originatingAddress);
      if ('+918282828282' === message.originatingAddress) {
        let OTP = regex(message.body);
        // authenticateOTP(OTP);
      }
      console.info(message)
    });
    this.setState({
      sub
    });
  }

  componentWillUnmount() {
    this.state.sub.remove();
  }

  render() {
    let timePast = 0;
    if (this.state.startTime && this.state.currentTime) {
      timePast = this.state.currentTime - this.state.startTime;
    }
    return (
      <View style={styles.container}>
        {
          this.state.otpSent &&
          <Image
            style={styles.backgroundImage}
            source={{uri: 'data:image/jpeg;base64,'}}
          />
        }
        {
          this.state.otpSent
            ? <View style={styles.otpSectionContainer}>
              <Text style={styles.otpTitle}>Verification Code</Text>
              <Text style={styles.otpSubTitle}>Please type the verification code sent to
                (+91) {this.state.phone.value}.</Text>
              <View style={styles.otpInputWrapper}>
                <TextInput
                  style={styles.otpInput}
                  value={this.state.otp[0].toString()}
                  onChangeText={(value) => {
                    let otp = this.state.otp;
                    otp.splice(0, 1, value.charAt(0));
                    this.setState({otp});
                    if (value) {
                      this.otp1.focus();
                    }
                  }}
                  ref={(input) => {
                    this.otp0 = input
                  }}
                  underlineColorAndroid='transparent'
                  editable={true}
                  keyboardType={'numeric'}
                />
                <TextInput
                  style={styles.otpInput}
                  value={this.state.otp[1].toString()}
                  onChangeText={(value) => {
                    if (value) {
                      let otp = this.state.otp;
                      otp.splice(1, 1, value.charAt(0));
                      this.otp2.focus();
                      this.setState({otp});
                    }
                    else {
                      let otp = this.state.otp;
                      otp.splice(1, 1, value.charAt(0));
                      this.otp0.focus();
                      this.setState({otp});
                    }
                  }}
                  ref={(input) => {
                    this.otp1 = input
                  }}
                  underlineColorAndroid='transparent'
                  editable={true}
                  keyboardType={'numeric'}
                />
                <TextInput
                  style={styles.otpInput}
                  value={this.state.otp[2].toString()}
                  onChangeText={(value) => {
                    if (value) {
                      let otp = this.state.otp;
                      otp.splice(2, 1, value.charAt(0));
                      this.otp3.focus();
                      this.setState({otp});
                    }
                    else {
                      let otp = this.state.otp;
                      otp.splice(2, 1, value.charAt(0));
                      this.otp1.focus();
                      this.setState({otp});
                    }
                  }}
                  ref={(input) => {
                    this.otp2 = input
                  }}
                  underlineColorAndroid='transparent'
                  editable={true}
                  keyboardType={'numeric'}
                />
                <TextInput
                  style={styles.otpInput}
                  value={this.state.otp[3].toString()}
                  onChangeText={(value) => {
                    if (value) {
                      let otp = this.state.otp;
                      otp.splice(3, 1, value.charAt(0));
                      this.setState({otp});
                    }
                    else {
                      let otp = this.state.otp;
                      otp.splice(3, 1, value.charAt(0));
                      this.otp2.focus();
                      this.setState({otp});
                    }
                  }}
                  ref={(input) => {
                    this.otp3 = input
                  }}
                  underlineColorAndroid='transparent'
                  editable={true}
                  keyboardType={'numeric'}
                />
              </View>
              {
                this.state.timeout - timePast > 0
                  ? <Text style={styles.timeLeft}>{this.formatTime(this.state.timeout - timePast)}</Text>
                  : <View>
                    <TouchableNativeFeedback
                      onPress={() => this.retryOTP('text')}
                    >
                      <View style={styles.otpRetryButton}>
                        <Text style={styles.otpRetryButtonText}>Resend OTP via SMS</Text>
                      </View>
                    </TouchableNativeFeedback>
                    <TouchableNativeFeedback
                      onPress={() => this.retryOTP()}
                    >
                      <View style={styles.otpRetryButton}>
                        <Text style={styles.otpRetryButtonText}>Resend OTP via Voice Call</Text>
                      </View>
                    </TouchableNativeFeedback>
                  </View>

              }
            </View>
            : <View style={styles.phoneSectionContainer}>
              <Image
                style={styles.phoneIcon}
                source={{uri: 'data:image/png;base64,'}}
              />
              <View style={styles.phoneNumberContainer}>
                <Text style={styles.countryCode}>(+91)</Text>
                <TextInput
                  style={styles.phoneNumberInput}
                  onChangeText={(phone) => this.setState({phone: this.verifyPhone(phone)})}
                  value={this.state.phone.value}
                  keyboardType={'numeric'}
                  placeholder='Enter mobile number'
                  maxLength={10}
                  underlineColorAndroid='transparent'
                  onSubmitEditing={this.state.phone.valid ? this.submit : () => ToastAndroid.show('Check The Phone Number', ToastAndroid.SHORT)}
                />
              </View>
              <Text style={styles.phoneNumberMessage}>
                We will send you a one time SMS message. SMS rates may apply.
              </Text>
            </View>
        }
        <View>

        </View>
        {
          !this.state.otpSent
            ? <TouchableNativeFeedback
              onPress={this.state.phone.valid ? this.submit : () => ToastAndroid.show('Check The Phone Number', ToastAndroid.SHORT)}
              background={TouchableNativeFeedback.SelectableBackground()}>
              <View style={[styles.button, styles.sentOTPButton]}>
                <Text style={styles.buttonText}>Send OTP</Text>
              </View>
            </TouchableNativeFeedback>
            : <TouchableNativeFeedback
              onPress={this.submitOTP}
              background={TouchableNativeFeedback.SelectableBackground()}>
              <View style={[styles.button, styles.submitOTPButton]}>
                <Text style={styles.buttonText}>Submit OTP</Text>
              </View>
            </TouchableNativeFeedback>
        }
      </View>
    )
  }
}

const mapStateToProps = state => ({});

const mapDispatchToProps = dispatch => bindActionCreators({
  userDataUpdate: userDataUpdate,
  goTo: goTo,
}, dispatch);

export default connect(mapStateToProps, mapDispatchToProps)(Phone)